This Terraform configuration creates an AWS Route 53 public hosted zone for a domain and adds an `A` record that maps a domain name to an IPv4 address.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region used for Route 53 API operations."
  type        = string
  default     = "us-east-1"
}

variable "domain_name" {
  description = "The root domain name for the Route 53 hosted zone."
  type        = string
  default     = "example.com"
}

variable "record_name" {
  description = "The DNS record name to map to the IPv4 address."
  type        = string
  default     = "www.example.com"
}

